    opened=await window.__m05Test.open({name,v2ProfileRegistry:registry,testQuotaAfterWrite:true});if(!opened.ok)throw new Error(opened.error.code);const quotaCommit=await opened.value.commitV2Draft({workId:quotaWork.id,expectedDraftRevision:quotaDraft.value.revision,expectedWorkRevision:quotaSaved.value.revision,thumbnail:new Blob(['quota'])});opened.value.close();
