test('M15-6D2 detects a v1 draft changed during validation and serializes one target ID',async({page,context})=>{
  await ready(page);const other=await context.newPage();await ready(other);const name=dbName(),registry=m15Registry(),sourceSeed=m15V1Work('v1-draft-race');
  const draft=await page.evaluate(async({name,registry,sourceSeed})=>{const opened=await window.__m05Test.open({name,v2ProfileRegistry:registry});if(!opened.ok)throw new Error(opened.error.code);const saved=await opened.value.saveDraft({work:{...sourceSeed,status:'draft',name:'原始草稿'},step:'cut',expectedDraftRevision:null,baseRevision:null});opened.value.close();if(!saved.ok)throw new Error(saved.error.code);return saved.value;},{name,registry,sourceSeed});
  await page.evaluate(async({name,registry,revision})=>{type RaceState={reached:boolean;release:()=>void;result:Promise<{ok:boolean;code:string}>};const holder=window as unknown as {__m15DraftRace?:RaceState};let release:()=>void=()=>{};const gate=new Promise<void>(resolve=>{release=resolve;});const state:RaceState={reached:false,release,result:Promise.resolve({ok:false,code:'NOT_STARTED'})};holder.__m15DraftRace=state;state.result=(async()=>{const opened=await window.__m05Test.open({name,v2ProfileRegistry:registry,v2Validation:{crypto:{subtle:{digest:async(algorithm:AlgorithmIdentifier,data:BufferSource)=>{state.reached=true;await gate;return crypto.subtle.digest(algorithm,data);}}}}});if(!opened.ok)return {ok:false,code:opened.error.code};const result=await opened.value.saveV1DraftAsV2({sourceWorkId:'v1-draft-race',expectedSourceDraftRevision:revision,expectedSourceWorkRevision:null,newWorkId:'v2-race-target'});opened.value.close();return {ok:result.ok,code:result.ok?'OK':result.error.code};})();},{name,registry,revision:draft.revision});
  await page.waitForFunction(()=>Boolean((window as unknown as {__m15DraftRace?:{reached:boolean}}).__m15DraftRace?.reached));
  const modified=await other.evaluate(async({name,revision})=>{const opened=await window.__m05Test.open({name});if(!opened.ok)throw new Error(opened.error.code);const current=await opened.value.readDraft('v1-draft-race');if(!current.ok)throw new Error(current.error.code);const result=await opened.value.saveDraft({work:{...current.value.work,name:'并发草稿'},step:'preview',expectedDraftRevision:revision,baseRevision:null});opened.value.close();return result;},{name,revision:draft.revision});expect(modified.ok).toBe(true);if(!modified.ok)throw new Error('modify failed');
  await page.evaluate(()=>{const state=(window as unknown as {__m15DraftRace?:{release:()=>void}}).__m15DraftRace;if(!state)throw new Error('race state');state.release();});const raced=await page.evaluate(async()=>{const state=(window as unknown as {__m15DraftRace?:{result:Promise<{ok:boolean;code:string}>}}).__m15DraftRace;if(!state)throw new Error('race state');return state.result;});expect(raced).toEqual({ok:false,code:'REVISION_CONFLICT'});
  const results=await Promise.all([page,other].map(target=>target.evaluate(async({name,registry,revision})=>{const opened=await window.__m05Test.open({name,v2ProfileRegistry:registry});if(!opened.ok)throw new Error(opened.error.code);const result=await opened.value.saveV1DraftAsV2({sourceWorkId:'v1-draft-race',expectedSourceDraftRevision:revision,expectedSourceWorkRevision:null,newWorkId:'v2-one-winner'});opened.value.close();return result;},{name,registry,revision:modified.value.revision})));
  expect(results.filter(item=>item.ok)).toHaveLength(1);expect(results.flatMap(item=>item.ok?[]:[item.error.code])).toEqual(['REVISION_CONFLICT']);
  const final=await other.evaluate(async({name,registry})=>{const opened=await window.__m05Test.open({name,v2ProfileRegistry:registry});if(!opened.ok)throw new Error(opened.error.code);const raceTarget=await opened.value.readAnyDraft('v2-race-target'),winner=await opened.value.readAnyDraft('v2-one-winner'),source=await opened.value.readAnyDraft('v1-draft-race');opened.value.close();return {raceTarget,winner,source};},{name,registry});
  expect(!final.raceTarget.ok&&final.raceTarget.error.code).toBe('NOT_FOUND');expect(final.winner.ok).toBe(true);expect(final.source.ok&&final.source.value.work.name).toBe('并发草稿');await removeDb(page,name);
});

